    [2] = {
      beijing = 3181,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "Pete's words suddenly sprung to my mind, and my heart plunged into a strange feeling of helplessness.",
      next = {3}
    },
    [3] = {
      beijing = 3181,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "This person before me went so much faster than anyone, and had gone so much farther.",
      next = {4}
    },
    [4] = {
      beijing = 3181,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "His thoughts and his mindset weren't something that normal people could keep up with. Anyone who wanted to stay shoulder-to-shoulder with him would have to put forth tremendous effort.",
      next = {5}
    },
    [5] = {
      beijing = 3181,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "So people would naturally keep their distance from him, perhaps for fear of holding him back, but probably for a number of reasons.",
