      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "Or perhaps he was already used to being on his own, embracing all his curiosities and persistence for the truth.",
      next = {9}
    },
    [9] = {
      beijing = 3181,
      dialog = 3,
      music = "204_Affectionate_Scene",
      renwu = "npc",
      sentence = "That empty feeling in my heart grew bigger and bigger, practically about to swallow it.",
